BEGIN;
SELECT set_config('app.current_user_id','00004001-0000-0000-0000-000000000001',true),set_config('app.current_tenant_id','00004002-0000-0000-0000-000000000001',true),set_config('app.correlation_id','00004003-0000-0000-0000-000000000001',true),set_config('app.current_operation','catalog.attributes.create',true);SET LOCAL ROLE mastererp_app;
DO $$ DECLARE item jsonb; caught boolean:=false;BEGIN item:=catalogo.atributo_crear('color','Color','SELECT',true,'["rojo","azul"]',NULL,1,'["ropa"]','attribute-key');IF item->>'type'<>'SELECT' OR jsonb_array_length(item->'category_slugs')<>1 THEN RAISE EXCEPTION 'Attribute create mismatch';END IF;PERFORM set_config('app.current_operation','catalog.attributes.update',true);item:=catalogo.atributo_actualizar('color',1,'{"name":"Color comercial","required":false}');IF (item->>'version')::int<>2 THEN RAISE EXCEPTION 'Attribute update mismatch';END IF;BEGIN PERFORM catalogo.atributo_actualizar('color',1,'{"name":"stale"}');EXCEPTION WHEN serialization_failure THEN caught:=true;END;IF NOT caught THEN RAISE EXCEPTION 'Stale attribute accepted';END IF;IF has_table_privilege('mastererp_app','catalogo.atributos_definiciones','INSERT,UPDATE,DELETE') THEN RAISE EXCEPTION 'Direct attribute DML leaked';END IF;END $$;ROLLBACK;
